8809: # ----------------------------------------------------------------------------- telemetry (wave 28, R17)
8810: #
8811: # ONE anonymised event per consultation and the operator's complaints, to the maintainer's intake
8812: # (the T-hub v2 contract: POST <base>/v2/events, POST <base>/v2/complaints). ON by default;
8813: # CODEX_CONSULT_TELEMETRY=off, or -Telemetry off for one run, switches it off (Get-TelemetrySwitch,
8814: # codex-consult-detached.ps1). Never in a consultation's critical path: after the ledger commit the
8815: # bridge appends one NDJSON line to <codex home>/telemetry-spool/<yyyy-mm-dd>.ndjson (UTC date;
8816: # Submit-TelemetryEvent) and starts ONE detached sender (codex-telemetry.ps1 -Flush -
8817: # Start-TelemetrySender), which it does not wait for. The event is built from the COMMITTED ledger
8818: # entry through a closed allowlist (ConvertTo-TelemetryDetails, New-TelemetryEvent): the engine, the
8819: # provider label, the model, the purpose, the outcome class, wall seconds, token and finding counts,
8820: # a few booleans, the panel size, the PowerShell version, the OS, the plugin version and a salted
8821: # instance id - never a task name, a brief, a prompt, a path, a thread id, a finding text, a key, a
8822: # user name or the machine name in clear.
8823: #
8824: # A spool line: {"v":1,"kind":"event"|"complaint","queued_unix":<s>,"body":"<the JSON sent>"} - the
8825: # body travels as a JSON STRING, so the sender posts exactly the bytes that were built (no
8826: # re-serialisation: PowerShell 7's ConvertFrom-Json would turn the ISO client_time into a date).
8827: # Every writer of a spool file opens it EXCLUSIVELY (FileShare.None, retried ~2 s): the bridge's
8828: # append, the sender's read and its rewrite; the sender removes what it delivered or dropped as a
8829: # multiset of exact lines, so lines appended while it posted stay.
8830: 
8831: $script:TelemetryAppId = 'codex-consult'
8832: $script:TelemetryDefaultUrl = 'https://xelth.com/T'
8833: $script:TelemetrySpoolDays = 7
8834: $script:TelemetryBatchMax = 100
8835: $script:TelemetryRetryAfterMax = 60
8836: $script:TelemetryTextMaxBytes = 8192
8837: # The closed sets of the event (anything else becomes 'other' / 'unknown')
8838: $script:TelemetryEventKeys = @('app_id', 'app_version', 'instance_id', 'event_type', 'severity', 'title', 'details', 'tags', 'client_time', 'os', 'runtime')
8839: $script:TelemetryDetailKeys = @('engine', 'provider', 'model', 'purpose', 'outcome', 'wall_seconds', 'tokens', 'findings', 'structured', 'format_retry', 'denial_retry', 'timeout_continue', 'panel_size', 'ps_version', 'os', 'bridge_version')
8840: $script:TelemetryFailureClasses = @('auth', 'quota', 'capability', 'transport', 'permission', 'operator', 'unknown', 'timeout', 'stalled', 'bridge')
8841: $script:BridgeVersion = $null
8842: 
8843: # The plugin's version (.claude-plugin/plugin.json next to this scripts directory), read once;
8844: # 'unknown' when it cannot be read.
8845: function Get-BridgeVersion {
8846:     if ($null -ne $script:BridgeVersion) { return $script:BridgeVersion }
8847:     $v = 'unknown'
8848:     try {
8849:         $mf = Join-Path (Join-Path (Split-Path -Parent $PSScriptRoot) '.claude-plugin') 'plugin.json'
8850:         if (Test-Path -LiteralPath $mf -PathType Leaf) {
8851:             $c = [string](Get-PropertyValue (ConvertFrom-Json -InputObject (Read-SharedText -Path $mf)) 'version' '')
8852:             if ($c -match '^[0-9A-Za-z][0-9A-Za-z.+-]{0,31}$') { $v = $c }
8853:         }
8854:     } catch { }
8855:     $script:BridgeVersion = $v
8856:     return $v
8857: }
8858: 
8859: # Where telemetry keeps its files, under the Codex home; $null without one. { Home; Spool (the
8860: # directory); Salt; Last (the last flush's result); Lock (the sender's lock); Notice (the marker of
8861: # the notice for this plugin version) }.
8862: function Get-TelemetryPaths {
8863:     $h = Get-CodexHome
8864:     if (-not $h) { return $null }
8865:     $spool = Join-Path $h 'telemetry-spool'
8866:     return [pscustomobject]@{
8867:         Home   = $h
8868:         Spool  = $spool
8869:         Salt   = (Join-Path $h 'telemetry-salt')
8870:         Last   = (Join-Path $spool '.last')
8871:         Lock   = (Join-Path $spool '.flush.lock')
8872:         Notice = (Join-Path $h ('telemetry-notice-' + (Get-BridgeVersion)))
8873:     }
8874: }
8875: 
8876: # The intake's base URL: CODEX_CONSULT_TELEMETRY_URL, else https://xelth.com/T. Only https - plain
8877: # http only for a LOOPBACK host (a local test intake: 127.0.0.1, localhost, ::1). { Base (no
8878: # trailing slash; '' when refused); Source; Error }.
8879: function Get-TelemetryUrl {
8880:     $raw = ([string][Environment]::GetEnvironmentVariable('CODEX_CONSULT_TELEMETRY_URL')).Trim()
8881:     $src = 'CODEX_CONSULT_TELEMETRY_URL'
8882:     if (-not $raw) { $raw = $script:TelemetryDefaultUrl; $src = 'the default' }
8883:     $r = [pscustomobject]@{ Base = ''; Source = $src; Error = '' }
8884:     $u = $null
8885:     if (-not [Uri]::TryCreate($raw, [UriKind]::Absolute, [ref]$u) -or -not $u.Host) {
8886:         $r.Error = "the intake URL '$raw' ($src) is not an absolute URL"
8887:         return $r
8888:     }
8889:     if ($u.Scheme -ne 'https' -and -not ($u.Scheme -eq 'http' -and $u.IsLoopback)) {
8890:         $r.Error = "the intake URL '$raw' ($src) is refused: only https (plain http only for a loopback test intake)"
8891:         return $r
8892:     }
8893:     $r.Base = $raw.TrimEnd('/')
8894:     return $r
8895: }
8896: 
8897: # The instance id: the lowercase hex SHA-256 of the 32 salt bytes followed by the UTF-8 bytes of
8898: # the machine name - the machine name never leaves in clear, and a new salt makes a new instance.
8899: # The salt: <codex home>/telemetry-salt, 64 lowercase hex digits, created ONCE (-Create; a racing
8900: # run's salt wins - the file is moved into place only when absent). '' without a salt (and not
8901: # -Create) or when it cannot be made.
8902: function Get-TelemetryInstanceId {
8903:     param([switch]$Create)
8904:     $p = Get-TelemetryPaths
8905:     if (-not $p) { return '' }
8906:     $hex = ''
8907:     if ([IO.File]::Exists($p.Salt)) { $hex = (Read-SharedText -Path $p.Salt).Trim() }
8908:     if ($hex -cnotmatch '^[0-9a-f]{64}$') {
8909:         if (-not $Create) { return '' }
8910:         try {
8911:             [void][IO.Directory]::CreateDirectory($p.Home)
8912:             # a racing run (a panel's members) may have moved its salt into place meanwhile: that
8913:             # one is taken; only a salt that is still unreadable is replaced (a new instance)
8914:             if ([IO.File]::Exists($p.Salt)) {
8915:                 $again = (Read-SharedText -Path $p.Salt).Trim()
8916:                 if ($again -cmatch '^[0-9a-f]{64}$') { $hex = $again } else { [IO.File]::Delete($p.Salt) }
8917:             }
8918:             if ($hex -cnotmatch '^[0-9a-f]{64}$') {
8919:                 $bytes = New-Object byte[] 32
8920:                 $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
8921:                 try { $rng.GetBytes($bytes) } finally { $rng.Dispose() }
8922:                 $tmp = "$($p.Salt).$([guid]::NewGuid().ToString('N')).tmp"
8923:                 Write-Utf8NoBom -Path $tmp -Text ((ConvertTo-HexString $bytes) + "`n")
8924:                 # moved into place only when absent: a salt another run moved there first wins
8925:                 try { [IO.File]::Move($tmp, $p.Salt) } catch { try { [IO.File]::Delete($tmp) } catch { } }
8926:                 $hex = (Read-SharedText -Path $p.Salt).Trim()
8927:             }
8928:         } catch { return '' }
8929:         if ($hex -cnotmatch '^[0-9a-f]{64}$') { return '' }
8930:     }
8931:     $salt = New-Object byte[] 32
8932:     for ($i = 0; $i -lt 32; $i++) { $salt[$i] = [Convert]::ToByte($hex.Substring($i * 2, 2), 16) }
8933:     $name = $script:Utf8NoBom.GetBytes([string][Environment]::MachineName)
8934:     $all = New-Object byte[] ($salt.Length + $name.Length)
8935:     [Array]::Copy($salt, 0, $all, 0, $salt.Length)
8936:     [Array]::Copy($name, 0, $all, $salt.Length, $name.Length)
8937:     return (Get-Sha256Hex -Bytes $all)
8938: }
8939: 
8940: # 'windows 10.0.26200' | 'linux <major>.<minor>' | 'macos <major>.<minor>' - the family and version.
8941: function Get-TelemetryOs {

8941: function Get-TelemetryOs {
8942:     $ver = [Environment]::OSVersion.Version
8943:     if ($script:OnWindows) { return "windows $($ver.Major).$($ver.Minor).$($ver.Build)" }
8944:     if ($IsMacOS) { return "macos $($ver.Major).$($ver.Minor)" }
8945:     return "linux $($ver.Major).$($ver.Minor)"
8946: }
8947: 
8948: # 'powershell 5.1' (Windows PowerShell) | 'pwsh 7.x'.
8949: function Get-TelemetryRuntime {
8950:     $v = $PSVersionTable.PSVersion
8951:     return "$(if ($script:LegacyPS) { 'powershell' } else { 'pwsh' }) $($v.Major).$($v.Minor)"
8952: }
8953: 
8954: # A value of the event from a closed pattern: the value when it matches, else $Other ('' in:
8955: # $Empty).
8956: function Get-TelemetryToken {
8957:     param([string]$Value, [string]$Pattern, [string]$Empty = 'unknown', [string]$Other = 'other')
8958:     $v = ([string]$Value).Trim()
8959:     if (-not $v) { return $Empty }
8960:     if ($v -cmatch $Pattern) { return $v }
8961:     return $Other
8962: }
8963: 
8964: # A non-negative whole number of the entry, or $null.
8965: function Get-TelemetryCount {
8966:     param($Value)
8967:     if ($null -eq $Value) { return $null }
8968:     $n = [long]0
8969:     if ([long]::TryParse([string]$Value, [System.Globalization.NumberStyles]::Integer, $script:Invariant, [ref]$n) -and $n -ge 0) { return $n }
8970:     return $null
8971: }
8972: 
8973: # The outcome of a committed ledger entry: { Outcome - usable | usable-after-continuation |
8974: # failed:<class>; Severity - info (usable) | warning (a provider limit or auth failure, or the
8975: # operator's -Kick) | error (every other failure); Class }. The class is the provider failure's
8976: # (auth, quota, capability, transport, permission, operator, unknown), else from the outcome:
8977: # timeout, stalled, or bridge (a failure of the bridge or the engine without a provider class).
8978: function Get-TelemetryOutcome {
8979:     param($Entry)
8980:     $bo = [string](Get-PropertyValue $Entry 'bridge_outcome' '')
8981:     if (Test-UsableOutcome $bo) {
8982:         $o = $(if ($bo -like '*after a timeout continuation*') { 'usable-after-continuation' } else { 'usable' })
8983:         return [pscustomobject]@{ Outcome = $o; Severity = 'info'; Class = '' }
8984:     }
8985:     $cls = [string](Get-PropertyValue (Get-PropertyValue $Entry 'provider_failure' $null) 'class' '')
8986:     if (-not $cls) {
8987:         if ($bo -like 'failed: timeout*') { $cls = 'timeout' }
8988:         elseif ($bo -like 'failed: stalled*') { $cls = 'stalled' }
8989:         elseif ($bo -like '*stopped by the operator*') { $cls = 'operator' }
8990:         else { $cls = 'bridge' }
8991:     }
8992:     if ($script:TelemetryFailureClasses -cnotcontains $cls) { $cls = 'unknown' }
8993:     $sev = $(if (@('auth', 'quota', 'operator') -contains $cls) { 'warning' } else { 'error' })
8994:     return [pscustomobject]@{ Outcome = "failed:$cls"; Severity = $sev; Class = $cls }
8995: }
8996: 
8997: # The event's `details` from a committed ledger entry - THE allowlist: every value is built here
8998: # from a closed set, a number, a boolean or a pattern-checked token (the provider label: letters,
8999: # digits, dot, dash, underscore; the model id: such segments joined by at most two ':' or '/', no
9000: # drive or path shape). Nothing else of the entry is read.
9001: function ConvertTo-TelemetryDetails {
9002:     param($Entry)
9003:     $rev = Get-PropertyValue $Entry 'reviewer' $null
9004:     $engine = [string](Get-PropertyValue $rev 'engine' 'codex')
9005:     if ($script:EngineNames -cnotcontains $engine) { $engine = 'other' }
9006:     $provider = Get-TelemetryToken -Value ([string](Get-PropertyValue $rev 'provider' '')) -Pattern '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'
9007:     $modelRaw = [string](Get-PropertyValue $rev 'model' '')
9008:     if (-not $modelRaw) { $modelRaw = [string](Get-PropertyValue $Entry 'model' '') }
9009:     $model = Get-TelemetryToken -Value $modelRaw -Pattern '^(?![A-Za-z]:)[A-Za-z0-9][A-Za-z0-9._+-]*(?:[:/][A-Za-z0-9][A-Za-z0-9._+-]*){0,2}$'
9010:     if ($model.Length -gt 80) { $model = 'other' }
9011:     $purpose = [string](Get-PropertyValue $Entry 'purpose' '')
9012:     if (-not $purpose) { $purpose = 'none' } elseif ($script:ConsultPurposes -cnotcontains $purpose) { $purpose = 'other' }
9013:     $usage = Get-PropertyValue $Entry 'usage' $null
9014:     $fc = Get-PropertyValue $Entry 'findings' $null
9015:     $fcount = { param($k) $n = Get-TelemetryCount (Get-PropertyValue $fc $k $null); if ($null -eq $n) { [long]0 } else { $n } }
9016:     $fr = Get-PropertyValue $Entry 'format_retry' $null
9017:     $dr = Get-PropertyValue $Entry 'denial_retry' $null
9018:     $tc = Get-PropertyValue $Entry 'timeout_continue' $null
9019:     $panelSize = [long]0
9020:     $pr = Get-PropertyValue $Entry 'panel' $null
9021:     if ($pr) { $ps = Get-TelemetryCount (Get-PropertyValue $pr 'of' $null); if ($null -ne $ps) { $panelSize = $ps } }
9022:     $wall = Get-TelemetryCount ([Math]::Round([double](Get-PropertyValue $Entry 'wall_seconds' 0)))
9023:     $psv = Get-TelemetryToken -Value ([string]$PSVersionTable.PSVersion) -Pattern '^[0-9][0-9A-Za-z.+-]{0,31}$'
9024:     return [pscustomobject]@{
9025:         engine           = $engine
9026:         provider         = $provider
9027:         model            = $model
9028:         purpose          = $purpose
9029:         outcome          = (Get-TelemetryOutcome $Entry).Outcome
9030:         wall_seconds     = $(if ($null -eq $wall) { [long]0 } else { $wall })
9031:         tokens           = [pscustomobject]@{
9032:             in     = (Get-TelemetryCount (Get-PropertyValue $usage 'input_tokens' $null))
9033:             cached = (Get-TelemetryCount (Get-PropertyValue $usage 'cached_input_tokens' $null))
9034:             out    = (Get-TelemetryCount (Get-PropertyValue $usage 'output_tokens' $null))
9035:         }
9036:         findings         = [pscustomobject]@{ blocker = (& $fcount 'blocker'); major = (& $fcount 'major'); minor = (& $fcount 'minor'); note = (& $fcount 'note') }
9037:         structured       = ((Get-PropertyValue $Entry 'structured' $false) -eq $true)
9038:         format_retry     = [bool]($fr -and (Get-PropertyValue $fr 'attempted' $false) -eq $true)
9039:         denial_retry     = [bool]($dr -and (Get-PropertyValue $dr 'attempted' $false) -eq $true)
9040:         timeout_continue = [bool]($tc -and -not ([string](Get-PropertyValue $tc 'outcome' '')).StartsWith('not attempted'))
9041:         panel_size       = $panelSize
9042:         ps_version       = $psv
9043:         os               = (Get-TelemetryOs)
9044:         bridge_version   = (Get-BridgeVersion)
9045:     }
9046: }
9047: 
9048: # The event of one committed consultation (the intake's v2 event; the keys in
9049: # $script:TelemetryEventKeys order). client_time is UTC.
9050: function New-TelemetryEvent {
9051:     param($Entry, [string]$InstanceId)
9052:     $d = ConvertTo-TelemetryDetails $Entry
9053:     $o = Get-TelemetryOutcome $Entry
9054:     return [pscustomobject]@{
9055:         app_id      = $script:TelemetryAppId
9056:         app_version = (Get-BridgeVersion)
9057:         instance_id = $InstanceId
9058:         event_type  = 'consultation'
9059:         severity    = $o.Severity
9060:         title       = $o.Outcome
9061:         details     = $d
9062:         tags        = [object[]]@($d.engine, $d.provider)
9063:         client_time = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ', $script:Invariant)
9064:         os          = (Get-TelemetryOs)
9065:         runtime     = (Get-TelemetryRuntime)
9066:     }
9067: }
9068: 
9069: # Opens a spool file EXCLUSIVELY (FileShare.None), retrying for about 2 s; $null when it does not
9070: # exist ($Mode Open) or stays busy.
9071: function Open-TelemetrySpoolFile {

9071: function Open-TelemetrySpoolFile {
9072:     param([string]$Path, [System.IO.FileMode]$Mode = [System.IO.FileMode]::Open)
9073:     for ($i = 0; $i -lt 40; $i++) {
9074:         if ($Mode -eq [System.IO.FileMode]::Open -and -not [IO.File]::Exists($Path)) { return $null }
9075:         try { return (New-Object System.IO.FileStream($Path, $Mode, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)) } catch { Start-Sleep -Milliseconds 50 }
9076:     }
9077:     return $null
9078: }
9079: 
9080: # The non-empty lines of an open spool file (UTF-8), from its start.
9081: function Read-TelemetryStreamLines {
9082:     param($Stream)
9083:     $Stream.Position = 0
9084:     $sr = New-Object System.IO.StreamReader($Stream, $script:Utf8NoBom, $false, 4096, $true)
9085:     try { $text = $sr.ReadToEnd() } finally { $sr.Dispose() }
9086:     return , ([string[]]@($text -split "`n" | ForEach-Object { $_.TrimEnd("`r") } | Where-Object { $_ }))
9087: }
9088: 
9089: # Appends ONE line to today's spool file (UTC date): {v, kind, queued_unix, body}. '' when written,
9090: # else why not (never throws).
9091: function Add-TelemetrySpoolLine {
9092:     param([string]$Kind, [string]$BodyJson)
9093:     try {
9094:         $p = Get-TelemetryPaths
9095:         if (-not $p) { return 'no codex home (CODEX_HOME, else ~/.codex)' }
9096:         [void][IO.Directory]::CreateDirectory($p.Spool)
9097:         $line = ConvertTo-Json -Compress -InputObject ([pscustomobject]@{ v = 1; kind = $Kind; queued_unix = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds(); body = $BodyJson })
9098:         $file = Join-Path $p.Spool ([DateTime]::UtcNow.ToString('yyyy-MM-dd', $script:Invariant) + '.ndjson')
9099:         $fs = Open-TelemetrySpoolFile -Path $file -Mode ([System.IO.FileMode]::OpenOrCreate)
9100:         if (-not $fs) { return "the spool file '$file' stayed busy" }
9101:         try {
9102:             [void]$fs.Seek(0, [System.IO.SeekOrigin]::End)
9103:             $bytes = $script:Utf8NoBom.GetBytes($line + "`n")
9104:             $fs.Write($bytes, 0, $bytes.Length)
9105:             $fs.Flush()
9106:         } finally { $fs.Dispose() }
9107:         return ''
9108:     } catch { return (ConvertTo-OneLine $_.Exception.Message) }
9109: }
9110: 
9111: # One spool line parsed: { Line; Kind; Queued (unix s); Body (the JSON text) }, or $null when it is
9112: # not a spool line.
9113: function ConvertFrom-TelemetrySpoolLine {
9114:     param([string]$Line)
9115:     try { $o = ConvertFrom-Json -InputObject $Line } catch { return $null }
9116:     if (-not (Test-IsJsonObject $o)) { return $null }
9117:     $kind = [string](Get-PropertyValue $o 'kind' '')
9118:     $body = Get-PropertyValue $o 'body' $null
9119:     $q = Get-TelemetryCount (Get-PropertyValue $o 'queued_unix' $null)
9120:     if (@('event', 'complaint') -cnotcontains $kind -or -not ($body -is [string]) -or -not $body -or $null -eq $q) { return $null }
9121:     return [pscustomobject]@{ Line = $Line; Kind = $kind; Queued = $q; Body = [string]$body }
9122: }
9123: 
9124: # Starts THE detached sender: `<this host> -NoProfile [-ExecutionPolicy Bypass] -File
9125: # codex-telemetry.ps1 -Flush -Telemetry on`, hidden (Windows: ShellExecute - no handle of this
9126: # process is inherited, the caller's pipes close when the bridge exits; elsewhere /bin/sh -c 'exec
9127: # nohup ... </dev/null >/dev/null 2>&1'), WITHOUT the coordinator's host markers (Hide-HostMarkers,
9128: # like every engine child), in the temp directory; never waited for. '' when started, else why not.
9129: function Start-TelemetrySender {
9130:     $self = Join-Path $PSScriptRoot 'codex-telemetry.ps1'
9131:     if (-not [IO.File]::Exists($self)) { return "'$self' does not exist" }
9132:     $hostExe = (Get-Process -Id $PID).Path
9133:     $cwd = [IO.Path]::GetTempPath()
9134:     $hidden = $null
9135:     try {
9136:         $hidden = Hide-HostMarkers
9137:         if ($script:OnWindows) {
9138:             $argLine = '-NoProfile -ExecutionPolicy Bypass -File ' + (ConvertTo-ProcArg $self) + ' -Flush -Telemetry on'
9139:             $null = Start-Process -FilePath $hostExe -ArgumentList $argLine -WorkingDirectory $cwd -WindowStyle Hidden
9140:         } else {
9141:             $q = { param([string]$s) "'" + $s.Replace("'", "'\''") + "'" }
9142:             $psi = New-Object System.Diagnostics.ProcessStartInfo
9143:             $psi.FileName = '/bin/sh'
9144:             [void]$psi.ArgumentList.Add('-c')
9145:             [void]$psi.ArgumentList.Add('exec nohup ' + (& $q $hostExe) + ' -NoProfile -File ' + (& $q $self) + ' -Flush -Telemetry on </dev/null >/dev/null 2>&1')
9146:             $psi.UseShellExecute = $false
9147:             $psi.WorkingDirectory = $cwd
9148:             $scrub = Remove-HostMarkersFromStartInfo $psi
9149:             if ($scrub) { throw "host markers could not be hidden ($scrub)" }
9150:             $null = [System.Diagnostics.Process]::Start($psi)
9151:         }
9152:         return ''
9153:     } catch {
9154:         return (ConvertTo-OneLine $_.Exception.Message)
9155:     } finally {
9156:         Restore-HostMarkers -Saved $hidden
9157:     }
9158: }
9159: 
9160: # The bridge's call after a ledger commit (a single run, a panel member, a detached background):
9161: # with telemetry on, the event of the committed $Entry goes into the spool and - unless -NoSender (a
9162: # panel member: its panel run starts one sender when every member is done; a run that keeps its
9163: # recovery record) - the detached sender is started. Silent, never throws, never waits: '' when
9164: # done, else why not (for a verbose trace only).
9165: function Submit-TelemetryEvent {
9166:     param($Entry, $Switch, [switch]$NoSender)
9167:     if (-not $Switch -or -not $Switch.On) { return '' }
9168:     try {
9169:         $id = Get-TelemetryInstanceId -Create
9170:         if (-not $id) { return 'no instance id (the salt could not be created)' }
9171:         $ev = New-TelemetryEvent -Entry $Entry -InstanceId $id
9172:         $why = Add-TelemetrySpoolLine -Kind 'event' -BodyJson (ConvertTo-Json -Compress -Depth 6 -InputObject $ev)
9173:         if ($why) { return $why }
9174:         if (-not $NoSender) { $why = Start-TelemetrySender }
9175:         return $why
9176:     } catch { return (ConvertTo-OneLine $_.Exception.Message) }
9177: }
9178: 
9179: # The first run after an install (no marker <codex home>/telemetry-notice-<plugin version>) prints
9180: # the five-line notice once and writes the marker - only while telemetry is on (off: nothing is
9181: # printed or written).
9182: function Show-TelemetryNotice {
9183:     param($Switch)
9184:     if (-not $Switch -or -not $Switch.On) { return }
9185:     $p = Get-TelemetryPaths
9186:     if (-not $p -or [IO.File]::Exists($p.Notice)) { return }
