9188:     $where = $(if ($u.Base) { $u.Base } else { $script:TelemetryDefaultUrl })
9189:     Write-Host "codex-consult: telemetry is ON (this notice is shown once per version): after each consultation ONE anonymised event goes to the maintainer's intake ($where) - engine, provider label, model, purpose, outcome class, wall seconds, token and finding counts, PowerShell version, OS, plugin version, a salted instance id." -ForegroundColor Yellow
9190:     Write-Host "codex-consult: never sent - task names, briefs, prompts, replies, finding texts, paths, thread ids, keys, user names, the machine name." -ForegroundColor Yellow
9191:     Write-Host "codex-consult: switch it off with CODEX_CONSULT_TELEMETRY=off (one run: -Telemetry off); events wait in $($p.Spool) and a background sender delivers them - never blocking a consultation." -ForegroundColor Yellow
9192:     Write-Host "codex-consult: complain or suggest: codex-consult.ps1 -Task <task> -Complain ""<text>"" (prints the exact payload and asks before sending); state: codex-telemetry.ps1 -Status." -ForegroundColor Yellow
9193:     Write-Host "codex-consult: installing this plugin means accepting these terms - README, section ""Telemetry (on by default)"", says what is sent and how to delete your data." -ForegroundColor Yellow
9194:     try {
