9200: # One POST of a JSON body to the intake: a TCP connect probe of $ConnectMs (the proxy's address when
9201: # the system proxy is used for the URL), then the request within what is left of $TotalMs. Delivered
9202: # only on a 2xx answer that is a JSON object with "ok": true - anything else (a timeout, an HTML page,
9203: # a 4xx/5xx, a JSON without ok) is not delivered. { Delivered; Status (0: no HTTP answer); Json;
9204: # Why; RetryAfter (seconds; -1 when not given) }.
9205: function Invoke-TelemetryPost {

9205: function Invoke-TelemetryPost {
9206:     param([string]$Url, [string]$Body, [int]$ConnectMs = 3000, [int]$TotalMs = 5000)
9207:     $r = [pscustomobject]@{ Delivered = $false; Status = 0; Json = $null; Why = ''; RetryAfter = -1 }
9208:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
9209:     if ($script:LegacyPS) { try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { } }
9210:     $uri = [Uri]$Url
9211:     $target = $uri
9212:     try {
9213:         $proxy = [Net.WebRequest]::DefaultWebProxy
9214:         if ($proxy -and -not $uri.IsLoopback -and -not $proxy.IsBypassed($uri)) { $pu = $proxy.GetProxy($uri); if ($pu) { $target = $pu } }
9215:     } catch { }
9216:     $tcp = New-Object System.Net.Sockets.TcpClient
9217:     try {
9218:         $ar = $tcp.BeginConnect($target.Host, $target.Port, $null, $null)
9219:         if (-not $ar.AsyncWaitHandle.WaitOne($ConnectMs)) { $r.Why = "no connection to $($target.Host):$($target.Port) within $([Math]::Round($ConnectMs / 1000.0, 1)) s"; return $r }
9220:         $tcp.EndConnect($ar)
9221:     } catch {
9222:         $ex = $_.Exception
9223:         while ($ex.InnerException) { $ex = $ex.InnerException }
9224:         $r.Why = "could not connect to $($target.Host):$($target.Port) ($(ConvertTo-OneLine $ex.Message))"
9225:         return $r
9226:     } finally { try { $tcp.Close() } catch { } }
9227:     $left = [int][Math]::Max(500, $TotalMs - $watch.ElapsedMilliseconds)
9228:     $resp = $null
9229:     try {
9230:         $req = [System.Net.HttpWebRequest]::Create($uri)
9231:         $req.Method = 'POST'
9232:         $req.ContentType = 'application/json; charset=utf-8'
9233:         $req.Accept = 'application/json'
9234:         $req.UserAgent = "codex-consult/$(Get-BridgeVersion)"
9235:         $req.Timeout = $left
9236:         $req.ReadWriteTimeout = $left
9237:         $req.AllowAutoRedirect = $false
9238:         $req.KeepAlive = $false
9239:         $bytes = $script:Utf8NoBom.GetBytes($Body)
9240:         $req.ContentLength = $bytes.Length
9241:         $s = $req.GetRequestStream()
9242:         try { $s.Write($bytes, 0, $bytes.Length) } finally { $s.Dispose() }
9243:         $resp = $req.GetResponse()
9244:     } catch {
9245:         $ex = $_.Exception
9246:         while ($ex -and -not ($ex -is [System.Net.WebException])) { $ex = $ex.InnerException }
9247:         if ($ex -and $ex.Response) { $resp = $ex.Response }
9248:         else {
9249:             $m = $_.Exception
9250:             while ($m.InnerException) { $m = $m.InnerException }
9251:             $r.Why = "no answer ($(ConvertTo-OneLine $m.Message))"
9252:             return $r
9253:         }
9254:     }
9255:     try {
9256:         $r.Status = [int]$resp.StatusCode
9257:         $ctype = [string]$resp.ContentType
9258:         $ra = [string]$resp.Headers['Retry-After']
9259:         if ($ra) {
9260:             $sec = 0
9261:             if ([int]::TryParse($ra.Trim(), [ref]$sec)) { $r.RetryAfter = [Math]::Max(0, $sec) }
9262:             else {
9263:                 $when = [DateTimeOffset]::MinValue
9264:                 if ([DateTimeOffset]::TryParse($ra, $script:Invariant, [System.Globalization.DateTimeStyles]::AssumeUniversal, [ref]$when)) { $r.RetryAfter = [int][Math]::Max(0, [Math]::Ceiling(($when - [DateTimeOffset]::UtcNow).TotalSeconds)) }
9265:             }
9266:         }
9267:         # the answer's text, at most 64 K characters
9268:         $sb = New-Object System.Text.StringBuilder
9269:         $rs = $resp.GetResponseStream()
9270:         try {
9271:             $sr = New-Object System.IO.StreamReader($rs, $script:Utf8NoBom)
9272:             $buf = New-Object char[] 8192
9273:             while ($sb.Length -lt 65536) {
9274:                 $n = $sr.Read($buf, 0, $buf.Length)
9275:                 if ($n -le 0) { break }
9276:                 [void]$sb.Append($buf, 0, $n)
9277:             }
9278:         } finally { $rs.Dispose() }
9279:         $text = $sb.ToString()
9280:         $obj = $null
9281:         try { if ($text.Trim().StartsWith('{')) { $obj = ConvertFrom-Json -InputObject $text } } catch { $obj = $null }
9282:         if ($obj -and (Test-IsJsonObject $obj)) { $r.Json = $obj }
9283:         if ($r.Status -ge 200 -and $r.Status -lt 300 -and $r.Json -and (Get-PropertyValue $r.Json 'ok' $false) -eq $true) {
9284:             $r.Delivered = $true
9285:         } elseif (-not $r.Json) {
9286:             $r.Why = "HTTP $($r.Status)$(if ($ctype) { " ($(($ctype -split ';')[0].Trim()))" }) is not the intake's JSON answer"
9287:         } else {
9288:             $r.Why = "HTTP $($r.Status)$(if ((Get-PropertyValue $r.Json 'error' '')) { ": $(ConvertTo-OneLine ([string]$r.Json.error))" } else { ' without ok: true' })"
9289:         }
9290:     } finally { try { $resp.Close() } catch { } }
9291:     return $r
9292: }
9293: 
9294: # POSTs with the intake's rate rule: a 429 whose Retry-After is at most 60 s is waited for and the
9295: # SAME request sent once more; a longer or missing Retry-After, or a second 429, stops there. No
9296: # other retry.
9297: function Invoke-TelemetrySend {
9298:     param([string]$Url, [string]$Body, [int]$ConnectMs = 3000, [int]$TotalMs = 5000)
9299:     $r = Invoke-TelemetryPost -Url $Url -Body $Body -ConnectMs $ConnectMs -TotalMs $TotalMs
9300:     if ($r.Status -eq 429) {
9301:         if ($r.RetryAfter -ge 0 -and $r.RetryAfter -le $script:TelemetryRetryAfterMax) {
9302:             Start-Sleep -Seconds $r.RetryAfter
9303:             $r = Invoke-TelemetryPost -Url $Url -Body $Body -ConnectMs $ConnectMs -TotalMs $TotalMs
9304:             if ($r.Status -eq 429) { $r.Why = 'HTTP 429 again after its Retry-After' }
9305:         } else {
9306:             $r.Why = "HTTP 429 (Retry-After $(if ($r.RetryAfter -ge 0) { "$($r.RetryAfter) s, more than $($script:TelemetryRetryAfterMax) s" } else { 'not given' }): not retried now)"
9307:         }
9308:     }
9309:     return $r
9310: }
9311: 
9312: # Removes $Lines (a multiset of exact lines) from a spool file under its exclusive handle - lines
9313: # appended meanwhile stay; an emptied file is deleted. '' when done, else why not.
9314: function Remove-TelemetrySpoolLines {
9315:     param([string]$Path, [string[]]$Lines)
9316:     if (@($Lines).Count -eq 0) { return '' }
9317:     $fs = Open-TelemetrySpoolFile -Path $Path
9318:     if (-not $fs) { return "the spool file '$Path' stayed busy" }
9319:     $empty = $false
9320:     try {
9321:         $remove = New-Object 'System.Collections.Generic.Dictionary[string,int]'
9322:         foreach ($l in $Lines) { if ($remove.ContainsKey($l)) { $remove[$l]++ } else { $remove[$l] = 1 } }
9323:         $keep = New-Object System.Collections.Generic.List[string]
9324:         foreach ($l in (Read-TelemetryStreamLines $fs)) {
9325:             if ($remove.ContainsKey($l) -and $remove[$l] -gt 0) { $remove[$l]--; continue }
9326:             $keep.Add($l)
9327:         }
9328:         $fs.SetLength(0)
9329:         $fs.Position = 0
9330:         if ($keep.Count -gt 0) {
9331:             $bytes = $script:Utf8NoBom.GetBytes(($keep.ToArray() -join "`n") + "`n")
9332:             $fs.Write($bytes, 0, $bytes.Length)
9333:         } else { $empty = $true }
9334:         $fs.Flush()
9335:     } finally { $fs.Dispose() }
9336:     if ($empty) { try { [IO.File]::Delete($Path) } catch { } }
9337:     return ''
9338: }
