9340: # The spool as it is: { Files; Events; Complaints; Invalid; Oldest (unix s or $null) } - read-only.
9341: function Get-TelemetrySpoolCounts {

9341: function Get-TelemetrySpoolCounts {
9342:     $c = [pscustomobject]@{ Files = 0; Events = 0; Complaints = 0; Invalid = 0; Oldest = $null }
9343:     $p = Get-TelemetryPaths
9344:     if (-not $p -or -not [IO.Directory]::Exists($p.Spool)) { return $c }
9345:     foreach ($f in @(Get-ChildItem -LiteralPath $p.Spool -File -Filter '*.ndjson' | Sort-Object Name)) {
9346:         $c.Files++
9347:         foreach ($l in @((Read-SharedText -Path $f.FullName) -split "`n" | ForEach-Object { $_.TrimEnd("`r") } | Where-Object { $_ })) {
9348:             $s = ConvertFrom-TelemetrySpoolLine $l
9349:             if (-not $s) { $c.Invalid++; continue }
9350:             if ($s.Kind -eq 'event') { $c.Events++ } else { $c.Complaints++ }
9351:             if ($null -eq $c.Oldest -or $s.Queued -lt $c.Oldest) { $c.Oldest = $s.Queued }
9352:         }
9353:     }
9354:     return $c
9355: }
