9357: # THE flush (codex-telemetry.ps1 -Flush; the detached sender): under the sender lock
9358: # <spool>/.flush.lock (held open exclusively - a concurrent sender is refused), every spool file
9359: # oldest first: lines older than 7 days and lines that are not spool lines are dropped; events go in
9360: # batches of at most 100 ({"events": [...]}) to <base>/v2/events, complaints one by one to
9361: # <base>/v2/complaints; the delivered and dropped lines are removed, the rest stays. The first
9362: # delivery that fails stops the flush (nothing is hammered; the next run's sender tries again).
9363: # Writes <spool>/.last {time, result, delivered, kept, dropped, http}. { Exit (0 done or nothing to
9364: # send, 1 something not delivered or the URL refused, 2 another sender holds the lock); Result;
9365: # Delivered; Kept; Dropped }.
9366: function Invoke-TelemetryFlush {
9367:     param([int]$ConnectMs = 3000, [int]$TotalMs = 5000)
9368:     $res = [pscustomobject]@{ Exit = 0; Result = ''; Delivered = 0; Kept = 0; Dropped = 0; Http = $null }
9369:     $p = Get-TelemetryPaths
9370:     if (-not $p) { $res.Exit = 1; $res.Result = 'no codex home (CODEX_HOME, else ~/.codex)'; return $res }
9371:     if (-not [IO.Directory]::Exists($p.Spool)) { $res.Result = 'nothing to send (no spool)'; return $res }
9372:     $lock = $null
9373:     try { $lock = New-Object System.IO.FileStream($p.Lock, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None) } catch {
9374:         $res.Exit = 2; $res.Result = 'another flush is running (its lock is held)'; return $res
9375:     }
9376:     try {
9377:         $url = Get-TelemetryUrl
9378:         $stop = ''
9379:         if ($url.Error) { $stop = $url.Error }
9380:         $cutoff = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds() - ($script:TelemetrySpoolDays * 86400)
9381:         foreach ($f in @(Get-ChildItem -LiteralPath $p.Spool -File -Filter '*.ndjson' | Sort-Object Name)) {
9382:             if ($stop) { break }
9383:             $fs = Open-TelemetrySpoolFile -Path $f.FullName
9384:             if (-not $fs) { continue }
9385:             try { $lines = Read-TelemetryStreamLines $fs } finally { $fs.Dispose() }
9386:             $drop = New-Object System.Collections.Generic.List[string]
9387:             $done = New-Object System.Collections.Generic.List[string]
9388:             $events = New-Object System.Collections.Generic.List[object]
9389:             $complaints = New-Object System.Collections.Generic.List[object]
9390:             foreach ($l in $lines) {
9391:                 $s = ConvertFrom-TelemetrySpoolLine $l
9392:                 if (-not $s -or $s.Queued -lt $cutoff) { $drop.Add($l); continue }
9393:                 if ($s.Kind -eq 'event') { $events.Add($s) } else { $complaints.Add($s) }
9394:             }
9395:             for ($i = 0; $i -lt $events.Count -and -not $stop; $i += $script:TelemetryBatchMax) {
9396:                 $batch = @($events.GetRange($i, [Math]::Min($script:TelemetryBatchMax, $events.Count - $i)))
9397:                 $r = Invoke-TelemetrySend -Url "$($url.Base)/v2/events" -Body ('{"events":[' + (@($batch | ForEach-Object { $_.Body }) -join ',') + ']}') -ConnectMs $ConnectMs -TotalMs $TotalMs
9398:                 if ($r.Status) { $res.Http = $r.Status }
9399:                 if ($r.Delivered) { foreach ($b in $batch) { $done.Add($b.Line) }; $res.Delivered += $batch.Count }
9400:                 else { $stop = $r.Why }
9401:             }
9402:             foreach ($cp in $complaints) {
9403:                 if ($stop) { break }
9404:                 $r = Invoke-TelemetrySend -Url "$($url.Base)/v2/complaints" -Body $cp.Body -ConnectMs $ConnectMs -TotalMs $TotalMs
9405:                 if ($r.Status) { $res.Http = $r.Status }
9406:                 if ($r.Delivered) { $done.Add($cp.Line); $res.Delivered++ } else { $stop = $r.Why }
9407:             }
9408:             $res.Dropped += $drop.Count
9409:             $why = Remove-TelemetrySpoolLines -Path $f.FullName -Lines ([string[]]@($done.ToArray() + $drop.ToArray()))
9410:             if ($why -and -not $stop) { $stop = $why }
9411:         }
9412:         $counts = Get-TelemetrySpoolCounts
9413:         $res.Kept = $counts.Events + $counts.Complaints + $counts.Invalid
9414:         if ($stop) {
9415:             $res.Exit = 1
9416:             $res.Result = "not delivered: $stop - delivered $($res.Delivered), kept $($res.Kept), dropped $($res.Dropped)"
9417:         } elseif ($res.Delivered -eq 0 -and $res.Dropped -eq 0) {
9418:             $res.Result = 'nothing to send'
9419:         } else {
9420:             $res.Result = "delivered $($res.Delivered), kept $($res.Kept), dropped $($res.Dropped)$(if ($res.Dropped -gt 0) { " (older than $($script:TelemetrySpoolDays) days or unreadable)" })"
9421:         }
9422:         try { Write-JsonFile -Path $p.Last -Object ([pscustomobject]@{ time = (Get-IsoTimestamp); result = $res.Result; delivered = $res.Delivered; kept = $res.Kept; dropped = $res.Dropped; http = $res.Http }) } catch { }
9423:     } finally { $lock.Dispose() }
9424:     return $res
9425: }
