9436: # {app_id, app_version, instance_id, text (at most 8 KiB of UTF-8), context {consultation - the
9437: # task's last ledger entry through the event's allowlist (ConvertTo-TelemetryDetails), or null;
9438: # bridge_version; os; runtime}, contact (or null)} is printed in full, then `send? [y/N]` unless
9439: # -Yes, then sent synchronously (10 s; a 429 as in Invoke-TelemetrySend). Delivered: the
9440: # public_ref is printed. Not delivered: the payload is kept in the spool as a complaint line - the
9441: # sender retries it. Independent of the telemetry switch (an explicit, confirmed send). Exit 0
9442: # delivered, 1 refused or not confirmed, 3 not delivered (kept in the spool).
9443: function Invoke-TelemetryComplaint {
9444:     param([string]$Text, [string]$Contact = '', $Entry = $null, [switch]$Yes, [int]$TotalMs = 10000)
9445:     $t = [string]$Text
9446:     if (-not $t.Trim()) { Write-Host 'codex-consult: -Complain needs a text: -Complain "<what went wrong or what you miss>".' -ForegroundColor Red; return 1 }
