9449:     $c = ([string]$Contact).Trim()
9450:     if ($c.Length -gt 256) { Write-Host 'codex-consult: -Contact takes at most 256 characters; nothing was sent.' -ForegroundColor Red; return 1 }
9451:     $p = Get-TelemetryPaths
9452:     if (-not $p) { Write-Host 'codex-consult: no codex home (CODEX_HOME, else ~/.codex): no instance id and no spool; nothing was sent.' -ForegroundColor Red; return 1 }
9453:     $u = Get-TelemetryUrl
