9457:     $payload = [pscustomobject]@{
9458:         app_id      = $script:TelemetryAppId
9459:         app_version = (Get-BridgeVersion)
9460:         instance_id = $id
9461:         text        = $t
9462:         context     = [pscustomobject]@{
9463:             consultation   = $(if ($Entry) { ConvertTo-TelemetryDetails $Entry } else { $null })
9464:             bridge_version = (Get-BridgeVersion)
9465:             os             = (Get-TelemetryOs)
9466:             runtime        = (Get-TelemetryRuntime)
9467:         }
9468:         contact     = $(if ($c) { $c } else { $null })
9469:     }
9470:     $json = ConvertTo-Json -Depth 6 -InputObject $payload
9471:     Write-Host "codex-consult: the complaint - exactly this JSON goes to $($u.Base)/v2/complaints:"
9472:     Write-Host $json
9473:     if (-not $Yes) {
9474:         $answer = ''
9475:         try {
9476:             if ([Console]::IsInputRedirected) { Write-Host 'send? [y/N] ' -NoNewline; $answer = [Console]::In.ReadLine() }
9477:             else { $answer = Read-Host 'send? [y/N]' }
9478:         } catch { $answer = '' }
9479:         if (([string]$answer).Trim() -notmatch '^(?i:y|yes)$') { Write-Host 'codex-consult: not sent (no confirmation; -Yes sends without asking).'; return 1 }
9480:     }
9481:     $r = Invoke-TelemetrySend -Url "$($u.Base)/v2/complaints" -Body $json -ConnectMs 3000 -TotalMs $TotalMs
9482:     if ($r.Delivered) {
9483:         $ref = ConvertTo-OneLine ([string](Get-PropertyValue $r.Json 'public_ref' ''))
9484:         Write-Host "codex-consult: complaint delivered - public_ref $(if ($ref) { $ref } else { '(none given)' }) (quote it when you write to the maintainer)."
9485:         return 0
9486:     }
9487:     $why = Add-TelemetrySpoolLine -Kind 'complaint' -BodyJson (ConvertTo-Json -Compress -Depth 6 -InputObject $payload)
9488:     if ($why) { Write-Host "codex-consult: not delivered ($($r.Why)); it could not be kept in the spool either ($why) - nothing was sent." -ForegroundColor Yellow; return 3 }
9489:     Write-Host "codex-consult: not delivered ($($r.Why)); kept in the spool as a complaint line ($($p.Spool)) - the sender retries it after the next consultation, or run codex-telemetry.ps1 -Flush." -ForegroundColor Yellow
9490:     return 3
9491: }

9409:             $why = Remove-TelemetrySpoolLines -Path $f.FullName -Lines ([string[]]@($done.ToArray() + $drop.ToArray()))
9410:             if ($why -and -not $stop) { $stop = $why }
9411:         }
