8287:     $ErrorActionPreference = 'Continue'
8288:     try {
8289:         $all = @()
8290:         if ($script:OnWindows) {
8291:             try { $all = @(Get-CimInstance -ClassName Win32_Process -Property ProcessId, ParentProcessId -ErrorAction Stop) } catch { $r.Denied = "the process table could not be read ($(ConvertTo-OneLine $_.Exception.Message))"; return $r }
8292:             if ($all.Count -eq 0) { $r.Denied = 'the process table came back empty'; return $r }
8293:         } elseif (-not (Get-Command pgrep -ErrorAction SilentlyContinue)) {
8294:             $r.Denied = 'pgrep is not available'
8295:             return $r
8296:         }
8297:         while ($queue.Count -gt 0) {
8298:             $cur = $queue.Dequeue()
8299:             $kids = @()
8300:             if ($script:OnWindows) {
8301:                 $kids = @($all | Where-Object { [int]$_.ParentProcessId -eq $cur -and [int]$_.ProcessId -ne $cur } | ForEach-Object { [int]$_.ProcessId })
8302:             } else {
8303:                 try { $kids = @(& pgrep -P $cur 2>$null) } catch { $kids = @() }
8304:             }
8305:             foreach ($k in $kids) {
8306:                 $n = 0
8307:                 if ([int]::TryParse(([string]$k).Trim(), [ref]$n) -and -not $found.Contains($n)) {
8308:                     $found.Add($n)
8309:                     $queue.Enqueue($n)
8310:                 }
8311:             }
8312:         }
8313:     } finally {
8314:         $ErrorActionPreference = $previous
8315:     }
8316:     $r.Pids = [int[]]$found.ToArray()
8317:     return $r
8318: }
