5541: # The host markers set in THIS process's environment, sorted ordinal: string[] (maybe empty).
5542: function Get-HostMarkerNames {
5543:     $names = New-Object System.Collections.Generic.List[string]
5544:     foreach ($k in @([Environment]::GetEnvironmentVariables().Keys)) {
5545:         $n = [string]$k
5546:         if ((Test-HostMarkerName $n) -and -not $names.Contains($n)) { $names.Add($n) }
5547:     }
5548:     $arr = [string[]]$names.ToArray()
5549:     [Array]::Sort($arr, [StringComparer]::Ordinal)
5550:     return , $arr
5551: }
