5553: # Removes the host markers from THIS process's environment right before a child is started
5554: # (Start-Process has no environment parameter on Windows PowerShell 5.1: the child inherits the
5555: # process's block) and returns what was removed (name -> value) for Restore-HostMarkers, which the
5556: # caller runs in a `finally` right after the start - the bridge's own process keeps its markers.
5557: # (wave 27c, D3 / F30-2) TRANSACTIONAL: the snapshot of every marker is taken FIRST, the removals
5558: # run inside `try`, and a removal that fails puts back everything removed so far and THROWS
5559: # "host markers could not be hidden (<name>: <why>)" - the caller refuses the start (a child never
5560: # starts with part of the markers). TEST HOOK (test mode only, D14): CODEX_CONSULT_TEST_HIDE_FAIL=
5561: # <name> makes the removal of that marker fail.
5562: function Hide-HostMarkers {
5563:     $saved = [ordered]@{}
5564:     foreach ($n in (Get-HostMarkerNames)) { $saved[$n] = [Environment]::GetEnvironmentVariable($n) }
5565:     $failOn = ([string](Get-TestHookValue 'CODEX_CONSULT_TEST_HIDE_FAIL')).Trim()
5566:     $removed = [ordered]@{}
5567:     $current = ''
5568:     try {
5569:         foreach ($n in @($saved.Keys)) {
5570:             $current = [string]$n
5571:             if ($failOn -and $current -ieq $failOn) { throw 'the removal was refused (test hook CODEX_CONSULT_TEST_HIDE_FAIL)' }
5572:             # a real null: PowerShell passes $null to a [string] argument as '' - which PowerShell 7
5573:             # (.NET) keeps as an EMPTY variable instead of removing it
5574:             [Environment]::SetEnvironmentVariable($current, [NullString]::Value)
5575:             $removed[$current] = $saved[$current]
5576:         }
5577:     } catch {
5578:         $why = ConvertTo-OneLine $_.Exception.Message
5579:         try { Restore-HostMarkers -Saved $removed } catch { }
5580:         throw "host markers could not be hidden ($($current): $why)"
5581:     }
5582:     return $saved
5583: }
