5585: function Restore-HostMarkers {
5586:     param($Saved)
5587:     if ($null -eq $Saved) { return }
5588:     foreach ($n in @($Saved.Keys)) { [Environment]::SetEnvironmentVariable([string]$n, [string]$Saved[$n]) }
5589: }
