5591: # (wave 27c, D3) THE way a child is started without the host markers: hides them (transactional,
5592: # Hide-HostMarkers), runs $Action, restores them in `finally`. A hide that fails runs nothing and
5593: # throws "host markers could not be hidden (<name>: <why>)". Returns what $Action returned.
5594: function Invoke-WithoutHostMarkers {
5595:     param([scriptblock]$Action)
5596:     $saved = Hide-HostMarkers
5597:     try { return (& $Action) } finally { Restore-HostMarkers -Saved $saved }
5598: }
