5600: # The same for a ProcessStartInfo (the launcher probes): its environment block without the markers.
5601: # (wave 27c, D4 / F30-4) '' when the block holds no marker afterwards, else why not (a removal that
5602: # failed, a marker still there) - never fails open silently: the caller then starts the probe
5603: # through Invoke-WithoutHostMarkers, or skips it. TEST HOOK (test mode only):
5604: # CODEX_CONSULT_TEST_PROBE_SCRUB_FAIL=1 makes this report a failure.
5605: function Remove-HostMarkersFromStartInfo {
5606:     param($StartInfo)
5607:     if ((Get-TestHookValue 'CODEX_CONSULT_TEST_PROBE_SCRUB_FAIL').Trim() -eq '1') { return 'the start-info block could not be scrubbed (test hook CODEX_CONSULT_TEST_PROBE_SCRUB_FAIL)' }
5608:     try {
5609:         $block = $StartInfo.EnvironmentVariables
5610:         foreach ($k in @($block.Keys)) { if (Test-HostMarkerName ([string]$k)) { $block.Remove([string]$k) } }
5611:         $left = @(@($block.Keys) | Where-Object { Test-HostMarkerName ([string]$_) })
5612:         if ($left.Count -gt 0) { return "the start-info block still holds $($left -join ', ')" }
5613:         return ''
5614:     } catch { return "the start-info block could not be scrubbed ($(ConvertTo-OneLine $_.Exception.Message))" }
5615: }
