1699:     if (-not $refusal -and $engineName -ne 'codex') { $refusal = Get-CmdArgvHazard -Launcher $Launcher -Argv $Argv }
1700:     if ($refusal) { $r.Refusal = [string]$refusal; return $r }
1701:     # (wave 27, R13 D4) the engine child never inherits the coordinator's host markers (the ledger's
1702:     # child_env_scrubbed); this process gets them back right after the start
1703:     $hiddenMarkers = $null
1704:     # (wave 27c, D3 / F30-2) transactional: a removal that fails put everything back already - the
1705:     # start is refused, nothing starts with part of the markers
1706:     try { $hiddenMarkers = Hide-HostMarkers } catch {
1707:         $r.Refusal = "bridge failure: $(ConvertTo-OneLine $_.Exception.Message)"
1708:         return $r
1709:     }
1710:     try {
1711:         $r.Proc = Start-Process -FilePath $Launcher -ArgumentList ((($Argv | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' ')) `
1712:             -WorkingDirectory $repoRoot -NoNewWindow -PassThru `
1713:             -RedirectStandardOutput $StdoutPath `
1714:             -RedirectStandardError $StderrPath `
1715:             -RedirectStandardInput $StdinPath
1716:     } catch {
1717:         $r.Error = ConvertTo-OneLine $_.Exception.Message
1718:     } finally {
1719:         Restore-HostMarkers -Saved $hiddenMarkers
1720:     }
1721:     return $r
1722: }
