5644: # (D3, F03-3, F04-5) The coordinator's host - a HINT inferred from its markers, never an identity:
5645: # `codex` (CODEX_SESSION_ID or CODEX_THREAD_ID - looked at FIRST: a codex session started from a
5646: # claude-code session inherits that session's markers, and its own are the innermost), (wave 27b)
5647: # `zcode` (looked at before claude-code: Z Code sets no claude-code marker of its own, so a
5648: # claude-code marker next to its own is taken as inherited) - (wave 27c, D20) ANY variable with the
5649: # prefix ZCODE_ (the shell tool of Z Code carries neither ZCODE_SESSION_ID nor ZCODE_PROJECT_DIR, but
5650: # its ZCODE_APP_VERSION, ZCODE_PROCESS_LABEL and more) -, `claude-code` (CLAUDECODE,
5651: # CLAUDE_CODE_ENTRYPOINT, or AI_AGENT starting with claude-code), else - no marker of any host - the
5652: # install path of the running script: a plugin cache under a directory `.zcode`, `.codex` or
5653: # `.claude` (`<dir>/plugins/...`) names that host. { Host; By ('markers' | 'path' | 'none') }.
5654: function Get-CoordinatorHostHint {
5655:     param([string]$ScriptPath = $PSScriptRoot)
5656:     $get = { param($n) [string][Environment]::GetEnvironmentVariable($n) }
5657:     if ((& $get 'CODEX_SESSION_ID') -or (& $get 'CODEX_THREAD_ID')) { return [pscustomobject]@{ Host = 'codex'; By = 'markers' } }
5658:     foreach ($k in @([Environment]::GetEnvironmentVariables().Keys)) { if (([string]$k).ToUpperInvariant().StartsWith('ZCODE_') -and (& $get ([string]$k))) { return [pscustomobject]@{ Host = 'zcode'; By = 'markers' } } }
5659:     if ((& $get 'CLAUDECODE') -or (& $get 'CLAUDE_CODE_ENTRYPOINT') -or (& $get 'AI_AGENT').StartsWith('claude-code', [StringComparison]::OrdinalIgnoreCase)) { return [pscustomobject]@{ Host = 'claude-code'; By = 'markers' } }
5660:     $p = [string]$ScriptPath
5661:     if ($p -match '(?i)[\\/]\.(zcode|codex|claude)[\\/]plugins[\\/]') {
5662:         return [pscustomobject]@{ Host = @{ zcode = 'zcode'; codex = 'codex'; claude = 'claude-code' }[$Matches[1].ToLowerInvariant()]; By = 'path' }
5663:     }
5664:     return [pscustomobject]@{ Host = 'unknown'; By = 'none' }
5665: }
