5674: # and without the matcher's and the seed's delimiters ('::', '[', ']', '|', ',', '#' -
5675: # Get-RosterStringProblem). Interior blanks are allowed. '' or why not ("is empty", "has
5676: # surrounding blanks", "must not contain '::'").
5677: function Get-IdentityStringProblem {
5678:     param($Value)
