5706: # (D3, F03-2, F04-4) The coordinator's identity, resolved ONCE at the start of a run (a panel member
5707: # and a detached background take their run's - never inferred again downstream): the value of
5708: # CODEX_CONSULT_COORDINATOR (optional) parsed by the reviewer matcher (ConvertFrom-ReviewerMatcher)
5709: # - `<provider> :: <model>` [` [<engine>]`], a roster position `#<n>` or a provider label - and the
5710: # host hint (Get-CoordinatorHostHint: markers, else the install path; no warning comes from it).
5711: # (wave 27c, D9 / F30-8, F32-6) A RESOLVED TRIPLE, through the same rules as a seated reviewer: `#n`
5712: # is that entry's provider, its model - else the model the bridge would run (the Codex config's,
5713: # $Defaults) - and its engine; a label is the model of its roster entry (else, for the config's
5714: # own provider, the config's model) - several entries of different models leave the model unnamed;
5715: # a lineage without an engine takes its roster entry's, else codex. (D10) Only a value that cannot be
5716: # PARSED - the matcher's grammar, the shared character rule (Get-IdentityStringProblem) - is refused
5717: # (Error). (D11 / F32-4) A coordinator no roster entry matches is said, not refused: in_roster false.
5718: # (D12 / F32-5) `#n` that names no position here is no refusal: unresolved "#n" and a warning. {
5719: # Record - the ledger's `coordinator` {provider, model, engine, host, host_by (markers | path |
5720: # none), source (explicit | inferred | none), in_roster ($null without a roster or an identity),
5721: # unresolved ($null, or the `#n` that named nothing)}; Error ('' or the refusal); Warnings }.
5722: function Resolve-CoordinatorIdentity {
5723:     param([string]$Value, $Roster = $null, $Defaults = $null, [string]$ScriptPath = $PSScriptRoot)
5724:     $hint = Get-CoordinatorHostHint -ScriptPath $ScriptPath
5725:     if ($null -eq $Defaults) { $Defaults = [pscustomobject]@{ Provider = 'openai'; Model = '' } }
5726:     $r = [pscustomobject]@{ Record = $null; Error = ''; Warnings = [string[]]@() }
5727:     $hasRoster = [bool]($Roster -and $Roster.Exists)
5728:     $mk = {
5729:         param($P, $M, $E, [string]$Src, $InRoster, $Unresolved)
5730:         [pscustomobject]@{ provider = $P; model = $M; engine = $E; host = $hint.Host; host_by = $hint.By; source = $Src; in_roster = $InRoster; unresolved = $Unresolved }
5731:     }
5732:     $v = ([string]$Value).Trim()
5733:     if (-not $v) {
5734:         $r.Record = & $mk $null $null $null $(if ($hint.Host -ne 'unknown') { 'inferred' } else { 'none' }) $null $null
5735:         return $r
5736:     }
5737:     $m = ConvertFrom-ReviewerMatcher -Matcher $v
5738:     $why = [string]$m.Error
5739:     if (-not $why -and $m.Kind -ne 'position') {
5740:         $pp = Get-IdentityStringProblem ([string]$m.Provider)
5741:         if ($pp) { $why = "the provider '$($m.Provider)' $pp" }
5742:         elseif ($null -ne $m.Model) { $mp = Get-IdentityStringProblem ([string]$m.Model); if ($mp) { $why = "the model '$($m.Model)' $mp" } }
5743:     }
5744:     if ($why) {
5745:         $r.Error = "CODEX_CONSULT_COORDINATOR='$v' cannot be used: $why - give '<provider> :: <model>' (optionally ' [<engine>]'), a roster position '#<n>' or a provider label; nothing was started."
5746:         return $r
5747:     }
5748:     $entries = @()
5749:     if ($hasRoster) { $entries = @($Roster.Entries) }
5750:     $modelOf = { param($e) if ([string]$e.Model) { [string]$e.Model } elseif (-not [string]$e.Engine -or [string]$e.Engine -eq 'codex') { [string]$Defaults.Model } else { '' } }
5751:     if ($m.Kind -eq 'position') {
5752:         $entry = @($entries | Where-Object { [int]$_.Position -eq [int]$m.Position }) | Select-Object -First 1
5753:         if (-not $entry) {
5754:             $r.Record = & $mk $null $null $null 'explicit' $(if ($hasRoster) { $false } else { $null }) $v
5755:             $r.Warnings = [string[]]@("CODEX_CONSULT_COORDINATOR '$v' names no roster position here$(if ($hasRoster) { " (the roster has $($entries.Count) entries)" } else { ' (there is no reviewer roster)' }) - the coordinator is not known; no self-review warning can be given")
5756:             return $r
5757:         }
5758:         $em = & $modelOf $entry
5759:         $r.Record = & $mk ([string]$entry.Provider) $(if ($em) { $em } else { $null }) $(if ([string]$entry.Engine) { [string]$entry.Engine } else { 'codex' }) 'explicit' $true $null
5760:         return $r
5761:     }
5762:     $hits = @($entries | Where-Object { Test-ReviewerMatch -Parsed $m -Provider ([string]$_.Provider) -Model ([string]$_.Model) -Engine ([string]$_.Engine) })
5763:     $model = $m.Model
5764:     $engine = $(if ($m.Engine) { [string]$m.Engine } else { $null })
5765:     if ($m.Kind -eq 'lineage') {
5766:         if (-not $engine) { $engine = $(if ($hits.Count -gt 0 -and [string]$hits[0].Engine) { [string]$hits[0].Engine } else { 'codex' }) }
5767:     } else {
5768:         # a label: the model of its roster entries when they name ONE model (and one engine); none in
5769:         # the roster - the config's model for the config's own provider
5770:         $models = @($hits | ForEach-Object { & $modelOf $_ } | Where-Object { $_ } | Select-Object -Unique)
5771:         $engines = @($hits | ForEach-Object { if ([string]$_.Engine) { [string]$_.Engine } else { 'codex' } } | Select-Object -Unique)
5772:         if ($hits.Count -gt 0) {
5773:             if ($models.Count -eq 1 -and $engines.Count -eq 1 -and @($hits | Where-Object { -not (& $modelOf $_) }).Count -eq 0) { $model = [string]$models[0]; $engine = [string]$engines[0] }
5774:         } elseif ([string]$m.Provider -ceq [string]$Defaults.Provider -and [string]$Defaults.Model -and (-not $engine -or $engine -eq 'codex')) {
5775:             $model = [string]$Defaults.Model; $engine = 'codex'
5776:         }
5777:     }
5778:     $r.Record = & $mk ([string]$m.Provider) $(if ($model) { [string]$model } else { $null }) $engine 'explicit' $(if ($hasRoster) { [bool]($hits.Count -gt 0) } else { $null }) $null
5779:     return $r
5780: }
