5782: # (wave 27c, D9) How a seated reviewer - its RESOLVED provider, model and engine - relates to the
5783: # coordinator: 'own' (provider, model and engine all equal - "the coordinator's own model"),
5784: # 'provider' (the coordinator names only its provider - no model could be resolved - and the
5785: # reviewer is of that provider: the weaker warning), else ''. An explicit identity only (an inferred
5786: # host names no model); the provider and the model compared ordinal.
5787: function Get-CoordinatorMatch {
5788:     param($Coordinator, [string]$Provider, [string]$Model, [string]$Engine)
5789:     if (-not $Coordinator -or [string](Get-PropertyValue $Coordinator 'source' '') -ne 'explicit') { return '' }
5790:     $cp = [string](Get-PropertyValue $Coordinator 'provider' '')
5791:     if (-not $cp -or $cp -cne $Provider) { return '' }
5792:     if (-not $Engine) { $Engine = 'codex' }
5793:     $cm = [string](Get-PropertyValue $Coordinator 'model' '')
5794:     $ce = [string](Get-PropertyValue $Coordinator 'engine' '')
5795:     if ($ce -and $ce -ne $Engine) { return '' }
5796:     if (-not $cm) { return 'provider' }
5797:     if ($cm -ceq $Model -and (-not $ce -or $ce -eq $Engine)) { return 'own' }
5798:     return ''
5799: }
