5801: # (D3) Whether a seated reviewer is the coordinator's own model (Get-CoordinatorMatch 'own').
5802: function Test-CoordinatorReviewer {
5803:     param($Coordinator, [string]$Provider, [string]$Model, [string]$Engine)
5804:     return ((Get-CoordinatorMatch -Coordinator $Coordinator -Provider $Provider -Model $Model -Engine $Engine) -eq 'own')
