5807: # The coordinator as shown (the dry run, the warning): `<provider> :: <model>` (` [<engine>]` when
5808: # not codex), a label alone, or `(no identity given)`; then the host hint and the source; (wave 27c)
5809: # an unresolved `#n`, and "(not in the roster - no reviewer can match it)" (D11).
5810: function Format-CoordinatorText {
5811:     param($Coordinator)
5812:     if (-not $Coordinator) { return '(none)' }
5813:     $p = [string](Get-PropertyValue $Coordinator 'provider' '')
5814:     $m = [string](Get-PropertyValue $Coordinator 'model' '')
5815:     $e = [string](Get-PropertyValue $Coordinator 'engine' '')
5816:     $un = [string](Get-PropertyValue $Coordinator 'unresolved' '')
5817:     $who = '(no identity given - CODEX_CONSULT_COORDINATOR is not set)'
5818:     if ($un) { $who = "$un (names no roster position here)" }
5819:     elseif ($p) {
5820:         $who = $(if ($m) { "$p :: $m" } else { "$p (model not named)" })
5821:         if ($e -and $e -ne 'codex') { $who += " [$e]" }
5822:     }
5823:     $by = [string](Get-PropertyValue $Coordinator 'host_by' 'markers')
5824:     $text = "$who; host $([string](Get-PropertyValue $Coordinator 'host' 'unknown')) ($(if ($by -eq 'path') { 'inferred from the install path, a hint' } else { 'inferred, a hint' })); source $([string](Get-PropertyValue $Coordinator 'source' 'none'))"
5825:     if ((Get-PropertyValue $Coordinator 'in_roster' $null) -eq $false -and -not $un) { $text += ' (not in the roster - no reviewer can match it)' }
5826:     return $text
5827: }
