8405: # (wave 26c, D1 / F26-1, F25-2) The member TAKES the operator's kick: (wave 27c, D1) it writes the
8406: # acknowledgement <kick file>.ack - atomically - holding the request's id and the result: "stopped"
8407: # (the turn is being stopped) or "late" (the turn had already finished, the outcome stays), and
8408: # removes the kick file. The callers wait for THEIR id. Never throws.
8409: function Confirm-Kick {
8410:     param([string]$KickPath, [string]$What = 'stopped')
8411:     if (-not $KickPath) { return }
8412:     $req = Read-KickRecord -Path $KickPath
8413:     try { Write-TextAtomic -Path "$KickPath.ack" -Text ((ConvertTo-Json -Compress -InputObject ([pscustomobject]@{ id = $req.Id; result = $What; when = (Get-IsoTimestamp); pid = $PID })) + "`n") } catch { }
8414:     $null = Remove-PendingFile -Path $KickPath
8415: }
8416: # (wave 26c, D3) The bytes appended to an event stream since byte $Offset, and the COMPLETE lines
8417: # among them: { Offset (the new end); Bytes (the growth - any byte counts as activity); Lines
8418: # (string[], the complete lines, UTF-8); Carry (byte[]: the unfinished last line, completed by the
8419: # next read); Discarding (the unfinished line is an oversized one being skipped); Oversized (lines
8420: # discarded by this read) }. Shared read; a file that is absent or cannot be read yet counts as no
8421: # growth.
8422: # (wave 27c, D5 / F30-3, F32-8) BOUNDED: only the newly read bytes are scanned for line ends
8423: # ([Array]::IndexOf), the carry is the text after the last line end and is capped at $CarryCap (1
8424: # MiB) - a longer unfinished line is discarded up to its end and counted (Oversized); the stall
8425: # timer's activity is the byte count, independent of parsing.
8426: $script:StreamCarryCap = 1048576
8427: function Read-StreamChunk {

1220:     $kPath = Get-KickPath -TaskDir $kTaskDir -Nn $kickNn
1221:     # (wave 26c, D1) no such running member: exit 1, and a kick file of that number is removed
1222:     $kickFail = { param([string]$Why) if ([IO.Directory]::Exists($kTaskDir)) { $null = Remove-PendingFile -Path $kPath }; Write-Host "codex-consult: -Kick: $Why" -ForegroundColor Red; exit 1 }
1223:     if (-not [IO.Directory]::Exists($kTaskDir)) { & $kickFail "no task directory '$kTaskDir'." }
1224:     # (wave 27c, D1) an acknowledgement older than 60 s (nobody's anymore) is swept first
1225:     $null = Clear-StaleKickAck -KickPath $kPath
1226:     # a detached run named by -Id: the member must be one of ITS members, running
1227:     if ($want) {
1228:         $w8 = $want.Replace('-', '')
1229:         if ($w8.Length -gt 8) { $w8 = $w8.Substring(0, 8) }
1230:         $kRuns = @(Read-DetachedRuns -TaskDir $kTaskDir | Where-Object { $_.Id8.StartsWith($w8) -and ($want.Length -le 8 -or ($_.Record -and ([string]$_.Record.id).ToLowerInvariant().StartsWith($want))) })
1231:         if ($kRuns.Count -eq 0) { & $kickFail "no detached run $want in task $Task." }
1232:         if ($kRuns.Count -gt 1) { Stop-StatusQuery "-Id $want names $($kRuns.Count) detached runs of task $($Task); give more of the id." }
1233:         $kRec = $kRuns[0].Record
1234:         $kMem = @(@(Get-PropertyValue $kRec 'members' @()) | Where-Object { $_ -and [string](Get-PropertyValue $_ 'handoff' '') -eq $kickNn }) | Select-Object -First 1
1235:         if (-not $kMem) { & $kickFail "detached run $($kRuns[0].Id8) has no member with handoff $kickNn." }
1236:         if ([string]$kMem.state -ne 'running') { & $kickFail "member $kickNn of detached run $($kRuns[0].Id8) is not running (state $($kMem.state))." }
1237:     }
1238:     # the run's recovery record: a member's .consult.pending-<NN>.json, a single run's .consult.pending.json
1239:     $kItem = $null
1240:     foreach ($p in (Get-PendingPaths -TaskDir $kTaskDir)) {
1241:         $rd = Read-PendingFile -Path $p
1242:         if ($rd.Exists -and $rd.Record -and [string](Get-PropertyValue $rd.Record 'nn' '') -eq $kickNn) { $kItem = $rd.Record; break }
1243:     }
1244:     if (-not $kItem) { & $kickFail "no run with handoff $kickNn is in progress in task $Task (no recovery record names it)." }
1245:     $kChild = 0
1246:     [void][int]::TryParse([string](Get-PropertyValue $kItem 'child_pid' ''), [ref]$kChild)
1247:     if ([string]$kItem.state -ne 'running' -or $kChild -le 0 -or -not (Test-RecordedProcess -ProcessId $kChild -StartTime (ConvertTo-StartIso (Get-PropertyValue $kItem 'child_start_time' ''))).Alive) {
1248:         & $kickFail "the run with handoff $kickNn has no engine turn running (state $($kItem.state))."
1249:     }
1250:     # (wave 26c, D1 / F26-1; wave 27c, D1 / F30-1, F29-2, F32-1, F30-6) THE REQUEST: written atomically
1251:     # with an id - or, when a kick of this member is already pending, JOINED (its id taken, the file
1252:     # never overwritten). The member acknowledges with <kick file>.ack {id, result: stopped - its turn
1253:     # is being stopped | late - its turn had already finished, the outcome stays}. This caller waits
1254:     # up to 10 s for an acknowledgement with ITS id; only the creator of the request removes it after
1255:     # reading it (after a short grace, so a joiner reads it too), a joiner never.
1256:     $kAck = "$kPath.ack"
1257:     $kReq = New-KickRequest -KickPath $kPath
1258:     if ($kReq.Error) { Stop-StatusQuery "-Kick: the kick request could not be written ($($kReq.Error))." }
1259:     $kWatch = [System.Diagnostics.Stopwatch]::StartNew()
1260:     $kGot = $null
1261:     while ($kWatch.Elapsed.TotalSeconds -lt 10) {
1262:         $kRead = Read-KickRecord -Path $kAck
1263:         if ($kRead.Exists -and $kRead.Id -and $kRead.Id -eq $kReq.Id) { $kGot = $kRead; break }
1264:         Start-Sleep -Milliseconds 200
1265:     }
1266:     if (-not $kGot) {
1267:         Write-Host "codex-consult: -Kick: the run with handoff $kickNn did not acknowledge the kick within 10 s - the kick file stays ($kPath): the member takes it at its next poll; a run that has ended leaves it to the next run of that number, which removes it." -ForegroundColor Yellow
1268:         exit 3
1269:     }
1270:     if ($kReq.Created) {
1271:         Start-Sleep -Milliseconds 1000
1272:         if ((Read-KickRecord -Path $kAck).Id -eq $kReq.Id) { $null = Remove-PendingFile -Path $kAck }
1273:     }
1274:     if ($kGot.Result -eq 'late') {
1275:         Write-Host "codex-consult: -Kick: member $kickNn of task $Task had already finished - the kick is recorded as kick_late in its warnings, its outcome unchanged."
1276:         exit 0
1277:     }
1278:     Write-Host "codex-consult: -Kick: member $kickNn of task $Task stopped - it took the kick; its engine's process tree is being stopped and its partial output salvaged; it records ""failed: stopped by the operator (-Kick)"" (a format repair only: its first reply stands) - the panel goes on with the others."
1279:     exit 0
1280: }
